import django.db.models.deletion
from django.db import migrations, models


CARRY_REMARK = "Bonus already on this payroll before the Excess tab existed (carried over automatically)."


def carry_existing_bonuses(apps, schema_editor):
    """A bonus HR had set on a staff month payroll becomes an Excess (or, below zero, a Detection) entry, so the next
    Generate again keeps it instead of resetting it to 0. No payroll figure changes."""
    Payroll = apps.get_model("api", "Payroll")
    Entry = apps.get_model("api", "PayrollExcessEntry")
    History = apps.get_model("api", "PayrollExcessHistory")
    rows = Payroll.objects.filter(
        salary_mode="monthly", period_start__isnull=True, week_number__isnull=True
    ).exclude(bonus=0)
    for p in rows.iterator():
        kind = "excess" if p.bonus > 0 else "detection"
        amount = abs(p.bonus)
        entry = Entry.objects.create(
            employee_id=p.employee_id, month=p.month, year=p.year, kind=kind, amount=amount, remark=CARRY_REMARK,
            source="migrated", status="active", created_by_name="System", updated_by_name="System",
        )
        History.objects.create(
            entry=entry, employee_id=p.employee_id, month=p.month, year=p.year, kind=kind, action="added",
            previous_amount=None, new_amount=amount, remark=CARRY_REMARK, source="migrated", actor_name="System",
            payroll_net_before=p.final_salary, payroll_net_after=p.final_salary,
        )


